from .scfc import Scfc
from .exceptions import NoSuchParameter, NoSuchListParameter


class ScfcReplicator(object):
    """ Class for replicating parameters from one scfc file to another """

    def __init__(self, source_file_path, base_file_path, config_file, target_file_path):
        self._source_xml = Scfc(source_file_path)
        self._base_xml = Scfc(base_file_path)
        config = ScfcReplicatorConfig(config_file)
        self._node_identifiers = config.node_identifiers
        self._target_file_path = target_file_path

    def replicate(self):
        """ Replaces scfc parameters based from input config file and scfc files """
        for identifier in self._node_identifiers:
            source_nodes = self._find_nodes(self._source_xml, identifier)
            base_nodes = self._find_nodes(self._base_xml, identifier)
            for index in range(0, min(len(source_nodes), len(base_nodes))):
                self._modify_contents(identifier, base_nodes[index], source_nodes[index])

        self._base_xml.save(self._target_file_path)

    def _find_nodes(self, xml, identifier):
        nodes = xml.find_managed_objects(identifier['class_name'])
        if identifier['parameter_name'] == '':
            return nodes
        return [node for node in nodes if self._is_valid_node(node, identifier)]

    def _modify_contents(self, identifier, base_node, source_node):
        if identifier['parameter_name'] != '':
            base_param = self._find_param_node(base_node, identifier['parameter_name'], identifier['list_name'])
            source_param = self._find_param_node(source_node, identifier['parameter_name'], identifier['list_name'])
            if base_param is not None:
                base_param.value = source_param.value
        else:
            self._remove_node_children(base_node)
            self._copy_node_children(source_node, base_node)

    def _find_param_node(self, node, parameter_name, list_name):
        try:
            return self._find_list_node(node, list_name).find_param(parameter_name)
        except NoSuchParameter:
            return None

    @staticmethod
    def _find_list_node(node, list_name):
        try:
            return node.find_list_param(list_name)
        except NoSuchListParameter:
            return node

    @staticmethod
    def _remove_node_children(node):
        for child in node.xml.iterchildren():
            node.xml.remove(child)

    @staticmethod
    def _copy_node_children(source, target):
        for child in source.xml.iterchildren():
            target.xml.append(child)

    @staticmethod
    def _is_valid_node(node, identifier):
        try:
            if identifier['list_name'] != '':
                node.find_list_param(identifier['list_name']).find_params(identifier['parameter_name'])
            else:
                node.find_params(identifier['parameter_name'])
        except (NoSuchListParameter, NoSuchParameter):
            return False
        return True


class ScfcReplicatorConfig(object):
    """ Class to represent config file for scfc replication """

    def __init__(self, config_file):
        self._config_file = config_file
        self._node_identifiers = []
        file_content = self._read_config()
        self._parse_config(file_content)

    @property
    def node_identifiers(self):
        """ Returns a list of node search criteria based from the config file """
        return self._node_identifiers

    def _read_config(self):
        return [line.strip() for line in self._config_file.readlines()]

    def _parse_config(self, file_content):
        for line in file_content:
            class_name = line.split()[0]
            list_name = line.partition(' ')[2].split('/')[0] if '/' in line else ''
            parameter_name = line.partition(' ')[2].partition('/')[2] if '/' in line else line.partition(' ')[2]
            self._node_identifiers.append(
                {'class_name': class_name, 'list_name': list_name, 'parameter_name': parameter_name}
            )
